from pathlib import Path
import html
root=Path(__file__).parent
nav=[('index.html','Home'),('courses.html','Courses'),('about.html','About'),('contact.html','Contact')]
def page(file,title,content,description='',heart=False):
    links=''.join(f'<a href="{f}"'+(' aria-current="page"' if f==file else '')+f'>{label}</a>' for f,label in nav)
    header=f'''<a class="skip" href="#main">Skip to content</a><div class="wrap"><header class="site-header"><a class="logo" href="index.html" aria-label="Cardiobug home"><img src="assets/logo.svg" width="37" height="37" alt=""><span><strong>CARDIOBUG</strong><small>ACADEMY</small></span></a><button class="btn small menu-toggle" id="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu ☰</button><nav class="navigation" id="navigation" aria-label="Main navigation">{links}<a class="btn small" href="signin.html" data-auth-link>Sign in ↗</a><a class="btn primary small" href="courses.html">Start learning ↗</a></nav></header>'''
    footer='''<footer class="site-footer"><div class="footer-top"><div><a class="logo" href="index.html"><img src="assets/logo.svg" width="37" height="37" alt=""><span><strong>CARDIOBUG</strong><small>ACADEMY</small></span></a><p>A clearer understanding of the heart.<br>A stronger foundation for learning.</p></div><div class="footer-links"><strong>Explore</strong><a href="courses.html">Courses</a><a href="about.html">About the academy</a><a href="resources.html">Learning resources</a><a href="contact.html">Contact</a></div><div class="footer-links"><strong>Your learning</strong><a href="dashboard.html">Student dashboard</a><a href="signup.html">Create account</a><a href="admin.html">Course manager</a><a href="privacy.html">Privacy</a><a href="terms.html">Terms of use</a></div></div><div class="footer-bottom"><span>© 2026 Cardiobug. Introductory educational content.</span><span>No clinical advice or professional accreditation.</span><a href="contact.html">Support ↗</a></div></footer></div>'''
    doc=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#10152b"><meta name="description" content="{html.escape(description or title+' — Cardiobug cardiology education',quote=True)}"><meta name="referrer" content="strict-origin-when-cross-origin"><title>{html.escape(title)} | Cardiobug</title><link rel="icon" href="favicon.ico" sizes="any"><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title)} | Cardiobug"><meta property="og:description" content="Cardiobug cardiology learning. Preview clearly labeled sample courses."><meta property="og:image" content="https://kuniam68.github.io/Cardiology-/assets/social-card.png"><meta name="twitter:card" content="summary_large_image"><link rel="apple-touch-icon" href="assets/apple-touch-icon.png"><link rel="manifest" href="manifest.webmanifest"><link rel="stylesheet" href="assets/styles.css"><script type="module" src="assets/app.js"></script>{'<script type="module" src="assets/heart.js"></script>' if heart else ''}</head><body>{header}<main id="main"><div class="notice" id="catalog-notice">Sample learning library — course materials are being prepared.</div>{content}</main>{footer}</body></html>'''
    (root/file).write_text(doc)
# Original illustrated fallback retains anatomical proportions and great-vessel silhouettes.
fallback='''<svg id="heart-fallback" class="heart-fallback" viewBox="0 0 300 400" role="img" aria-label="Illustrated anatomical-inspired heart"><defs><radialGradient id="muscle" cx="30%" cy="30%"><stop stop-color="#da8b8e"/><stop offset=".45" stop-color="#ad5064"/><stop offset="1" stop-color="#562b43"/></radialGradient><linearGradient id="vein"><stop stop-color="#a1a8c9"/><stop offset="1" stop-color="#555e94"/></linearGradient></defs><path d="M99 164C69 124 70 80 78 55" fill="none" stroke="url(#vein)" stroke-width="34"/><path d="M153 164C129 97 150 42 191 57C223 68 213 117 213 154" fill="none" stroke="#c8747c" stroke-width="34"/><path d="M173 65l-6-33m25 29 5-29m10 41 18-26" stroke="#c8747c" stroke-width="13" stroke-linecap="round"/><path d="M91 139C40 139 34 195 62 261C83 311 125 352 160 371C200 331 236 261 229 204C223 154 195 126 157 151C131 127 111 128 91 139Z" fill="url(#muscle)"/><path d="M132 180C118 121 119 99 86 104L44 120" fill="none" stroke="url(#vein)" stroke-width="31" stroke-linecap="round"/><path d="M157 180c-14 57 15 96 6 164m-9-116 37 32m-38-71-57 29m61 33-26 39" fill="none" stroke="#e9b4a3" stroke-width="4" stroke-linecap="round"/></svg>'''
page('index.html','Learn the heart. Find your rhythm.',f'''<section class="hero"><div><div class="eyebrow">Cardiology, made clearer</div><h1>Learn the heart.<br>Find your<br><em>rhythm.</em></h1><p class="lead">From the first heartbeat to the first ECG. Build your understanding through focused lessons, clear explanations, and learning at your own pace.</p><div class="actions"><a class="btn primary" href="courses.html">Explore the courses <span>↗</span></a><a class="btn" data-featured-course href="course.html?id=heart-foundations">See where to start <span>→</span></a></div><p class="micro" data-curriculum-note>Clearly labeled sample courses · Real course materials coming later</p></div><div class="heart-stage">{fallback}<canvas id="heart-canvas" role="img" aria-label="Three-dimensional heart loading"></canvas><span class="heart-note">ANATOMY IN MOTION / A NEW PERSPECTIVE</span><div class="heart-bottom"><div><div class="heart-controls"><button class="btn small" id="heart-pause" aria-pressed="false">Pause motion Ⅱ</button><button class="btn small" id="heart-reset">Reset view ↻</button></div><div class="micro" id="heart-render-status" style="max-width:200px">Drag to explore · Illustrative anatomy</div></div><div class="rhythm"><small>THE RHYTHM OF LEARNING</small><br><strong>72 <small>BPM</small></strong><svg viewBox="0 0 160 40" aria-label="Decorative animated pulse trace"><path d="M0 23h33l8-7 6 14 9-28 12 36 10-22 8 7h74"/></svg><small>ILLUSTRATIVE TRACE</small></div></div></div></section><div class="trust-line"><span>BUILT FOR YOUR FIRST STEPS</span><b>Self-paced lessons</b><span>✦</span><b>Knowledge checks</b><span>✦</span><b>A clear learning path</b></div><section class="section"><div class="section-heading"><div><div class="eyebrow">01 / Choose your starting point</div><h2>Big ideas.<br>Clear foundations.</h2></div><a class="btn" href="courses.html">Browse all courses ↗</a></div><div class="grid" data-course-grid></div></section><section class="path"><div><div class="eyebrow">02 / Make learning a habit</div><h2>One lesson closer<br>to understanding.</h2><p class="lead">No overwhelming library. No race to the finish. A considered path from curiosity to a stronger foundation.</p><a class="btn primary" href="courses.html">Find your first course ↗</a></div><ol class="steps"><li><span class="number">01</span><div><h3>Choose your focus.</h3><p>Start with anatomy, electrical activity, or the principles of prevention.</p></div></li><li><span class="number">02</span><div><h3>Learn something that connects.</h3><p>Read a focused lesson and check your understanding before moving on.</p></div></li><li><span class="number">03</span><div><h3>Build on your progress.</h3><p>With an activated student account, keep your courses and completed lessons together.</p></div></li></ol></section><section class="cta"><div class="eyebrow">A good place to begin</div><h2>Understanding starts<br>with a little curiosity.</h2><p>Take your first lesson. Give your next question a stronger foundation.</p><a class="btn primary" data-first-lesson href="lesson.html?course=heart-foundations&lesson=chambers">Try a sample lesson ↗</a></section>''', 'Preview Cardiobug, a cardiology learning academy. Sample courses and lessons demonstrate the learning experience.',True)
page('courses.html','Courses','''<section class="page-head"><div class="eyebrow">The learning library</div><h1>Your next chapter<br>starts here.</h1><p class="lead">Explore the learning library by topic. Current example courses and lessons are labeled as samples while real materials are prepared.</p></section><div class="filters"><div class="field"><label for="course-search">Find a course</label><input id="course-search" type="search" placeholder="Try anatomy, ECG, or prevention" autocomplete="off"></div><div class="field"><label for="category">Topic</label><select id="category"><option value="">All topics</option><option>Foundations</option><option>ECG</option><option>Prevention</option></select></div></div><p class="count" id="course-count" role="status"></p><section class="grid" id="catalog" aria-label="Available courses"></section><section class="section"><div class="notice">These sample reading courses demonstrate lesson navigation and knowledge checks. They do not provide CME credits, professional certification, or a clinical qualification.</div><h2>Questions before you start?</h2><details class="faq"><summary>Do I need a medical background?</summary><p>The introductions assume no specialist cardiology knowledge. They build vocabulary and concepts; they do not replace formal medical education.</p></details><details class="faq"><summary>Can I preview the lessons?</summary><p>Yes. Every lesson is available to read without an account. Student accounts, once activated, add enrollment and saved progress.</p></details><details class="faq"><summary>Are these video courses?</summary><p>The current courses use reading lessons, visual illustrations, and knowledge checks. No video library is advertised or included.</p></details></section>''')
page('course.html','Explore a course','<div id="course-detail" class="section"><p>Loading course…</p></div>')
page('lesson.html','Your lesson','<div id="lesson-page"><section class="page-head"><h1>Loading your lesson…</h1></section></div>')
page('about.html','About the academy','''<section class="page-head"><div class="eyebrow">A considered approach to learning</div><h1>Complex subject.<br>Human explanations.</h1><p class="lead">Cardiobug is a starting point for understanding the cardiovascular system—one clear idea at a time.</p></section><section class="path"><div><h2>Built around<br>understanding.</h2><p class="lead" style="margin-top:25px">The heart is a connected system. Learning should feel connected, too.</p></div><div><p class="lead">The current sample lessons demonstrate how future courses will link structure, function, and everyday questions. Each course has a short sequence, explicit learning outcomes, and a knowledge check to help you reflect on what you have read.</p><a class="btn primary" href="courses.html">Explore the curriculum ↗</a></div></section><section class="section article"><h2>What you can expect</h2><p>Focused written lessons, a manageable learning path, and pointers to established public health information. You can preview all lessons without creating an account.</p><h2>Honest about the scope</h2><p>This academy currently offers foundational educational material. It is not a university, clinical service, or accredited training provider. The courses do not award professional qualifications or continuing medical education credits.</p><h2>About the content</h2><p>The current curriculum is clearly labeled sample material awaiting replacement, with links to further reading from established health organizations. Faculty profiles and clinical-review credentials have not been supplied; no instructor qualifications or endorsements are claimed.</p><h2>Learning with care</h2><p>Medical understanding develops with practice, context, and supervision. Do not use a lesson, knowledge check, or heart illustration to diagnose a condition or make treatment decisions. The 3D model is an original anatomical-inspired illustration and is not a validated anatomical reference.</p></section>''')
page('contact.html','Contact','''<section class="page-head"><div class="eyebrow">Let’s talk learning</div><h1>A question is<br>a good beginning.</h1><p class="lead">Questions about a course, your learning account, or an idea for the academy? Get in touch with the course team.</p></section><section class="contact-grid"><div class="content-panel"><h2>Send a course enquiry</h2><p>This form opens your email app with a draft when contact delivery is activated. You send the message from your own email account.</p><form id="contact-form" class="contact-form"><div class="field"><label for="contact-name">Your name</label><input name="name" id="contact-name" autocomplete="name" maxlength="100" required></div><div class="field"><label for="contact-reply">Email</label><input name="email" id="contact-reply" type="email" autocomplete="email" required maxlength="254"></div><div class="field"><label for="contact-subject">What is your question about?</label><select name="subject" id="contact-subject"><option>Course content</option><option>Account support</option><option>Privacy or account removal</option><option>Something else</option></select></div><div class="field"><label for="contact-message">Your message</label><textarea name="message" id="contact-message" maxlength="2000" required placeholder="Please do not include health records, passwords, or sensitive medical details."></textarea></div><button class="btn primary" type="submit">Open email draft ↗</button></form><div class="notice" id="contact-status" role="status"></div></div><div><h2>Here to help you learn.</h2><p class="lead" style="margin-top:20px" id="contact-email"></p><details class="faq"><summary>I cannot sign in.</summary><p>First check whether student accounts have been activated. If they have, use the password reset link, check your confirmation email, and make sure you are using the same email address.</p></details><details class="faq"><summary>Where is my progress?</summary><p>Progress is linked to your authenticated account after enrollment and completion of a lesson knowledge check. Sign into the same account to view it on the dashboard.</p></details><div class="notice">This is an educational website, not a medical service. For medical advice contact a qualified clinician. For an emergency, seek local emergency help.</div></div></section>''')
page('dashboard.html','Your dashboard','''<section class="page-head"><div class="eyebrow">Your learning space</div><h1 id="dashboard-name">Make room<br>for your next step.</h1><p class="lead">Your enrolled courses, completed lessons, and next chapter in one place.</p></section><div class="notice" id="dashboard-status" role="status"></div><section class="section" style="padding-top:0" id="dashboard-body"><p role="status">Loading your learning space…</p></section>''')

def auth(file,title,mode,fields,cta,links):
    page(file,title,f'''<section class="auth-wrap"><div class="content-panel"><div class="eyebrow">Your Cardiobug account</div><h1 style="margin-top:20px">{title}</h1><p style="color:var(--muted)">Learn at your pace. Keep your progress together.</p><form class="auth-form" id="auth-form" data-mode="{mode}">{fields}<button class="btn primary" type="submit">{cta} ↗</button></form><button class="btn" id="google-signin" hidden style="width:100%;margin-top:16px">Continue with Google</button><div class="notice" id="auth-status" role="status"></div><div class="auth-links">{links}</div></div><p class="micro">Your password is handled by the configured authentication provider. Never share your password with the academy team.</p></section>''')
email='<div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" maxlength="254" required></div>'
password='<div class="field"><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="current-password" required maxlength="128"></div>'
newpassword='<div class="field"><label for="password">Password · at least 12 characters</label><input id="password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></div>'
auth('signin.html','Welcome back.','signin',email+password,'Sign in','<a class="inline-link" href="forgot-password.html">Forgot password?</a><a class="inline-link" href="signup.html">Create an account</a>')
auth('signup.html','A fresh start.','signup','<div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" required maxlength="80"></div>'+email+newpassword+'<label class="terms-check"><input type="checkbox" required><span>I agree to the <a class="inline-link" href="terms.html">terms</a> and have read the <a class="inline-link" href="privacy.html">privacy information</a>.</span></label>','Create account','<span>Already learning with us?</span><a class="inline-link" href="signin.html">Sign in</a>')
auth('forgot-password.html','Reset your password.','forgot',email,'Send reset link','<a class="inline-link" href="signin.html">Back to sign in</a>')
auth('reset-password.html','Choose a new password.','reset-password',newpassword,'Update password','<a class="inline-link" href="dashboard.html">Open dashboard</a>')
page('resources.html','Learning resources','''<section class="page-head"><div class="eyebrow">Continue your curiosity</div><h1>Go a little deeper.</h1><p class="lead">Established public resources to support your introductory learning.</p></section><section class="article"><h2>Heart structure and function</h2><p>The US National Heart, Lung, and Blood Institute explains chambers, circulation, and how the heart works.</p><a class="btn" href="https://www.nhlbi.nih.gov/health/heart" target="_blank" rel="noopener noreferrer">NHLBI · How the heart works ↗</a><h2>Understanding an ECG</h2><p>MedlinePlus provides an overview of the electrocardiogram and what to expect from the test.</p><a class="btn" href="https://medlineplus.gov/lab-tests/electrocardiogram/" target="_blank" rel="noopener noreferrer">MedlinePlus · Electrocardiogram ↗</a><h2>Everyday cardiovascular health</h2><p>The American Heart Association’s Life’s Essential 8 introduces factors associated with cardiovascular health.</p><a class="btn" href="https://www.heart.org/en/healthy-living/healthy-lifestyle/lifes-essential-8" target="_blank" rel="noopener noreferrer">AHA · Life’s Essential 8 ↗</a><h2>A useful study habit</h2><p>After a lesson, explain the main idea in your own words. Write down one question you still have. Return to the lesson and further reading to refine your explanation.</p><div class="notice">External resources are independent of Cardiobug. A link does not imply endorsement, partnership, or accreditation.</div></section>''')
page('privacy.html','Privacy information','''<section class="page-head"><div class="eyebrow">Your information</div><h1>Privacy, explained.</h1><p class="lead">Last updated 16 November 2026. This describes the current implementation and its account setup requirements.</p></section><section class="article"><h2>Before account activation</h2><p>You can read course material without an account. When the authentication provider is not configured, signup and contact delivery are disabled and no account details are collected through those forms.</p><h2>Student accounts</h2><p>Once Supabase is configured, the authentication service processes your email, password, and chosen display name. The learning database stores your account identifier, enrolled course identifiers, completed lesson identifiers, and related timestamps. Passwords are handled by the authentication provider rather than placed in course source files.</p><h2>Session storage</h2><p>The sign-in session is stored in your browser tab’s session storage. It is used to keep authenticated requests associated with your account. Sign out on shared devices. This site does not add advertising trackers or analytics.</p><h2>Contact messages</h2><p>When an academy contact address is configured, the contact form opens a draft in your email app. A message is delivered only when you send it there. Do not include medical records, sensitive health information, or passwords.</p><h2>Hosting and external services</h2><p>GitHub Pages hosts this website. Google Fonts and jsDelivr serve fonts and application libraries, including the interactive heart renderer. If a Turnstile site key is configured, Cloudflare processes verification signals on authentication forms. Tokens are sent to Supabase when available. Enforcement remains disabled until the operator enables it in Supabase. These services receive connection information such as your IP address. Configured accounts use Supabase; optional Google sign-in is shown only when enabled. Further-reading links lead to independent websites.</p><h2>Access and removal</h2><p>Use the contact page to request account support or removal after the academy’s contact address is activated. The site operator must publish their legal identity, working contact address, retention policy, and any jurisdiction-specific disclosures before opening account registration to the public.</p><div class="notice">Operator identity, contact details, and a retention period have not yet been supplied. These details and the authentication provider’s settings must be finalized before public account registration.</div></section>''')
page('terms.html','Terms of use','''<section class="page-head"><div class="eyebrow">Learning responsibly</div><h1>A clear starting point.</h1><p class="lead">Last updated 16 November 2026.</p></section><section class="article"><h2>Educational use</h2><p>Cardiobug provides free introductory educational material about cardiovascular concepts. It does not provide medical diagnosis, individualized advice, or emergency services.</p><h2>Course scope</h2><p>Current courses and lessons are samples for demonstration. They consist of written lessons and knowledge checks. Completion does not confer a clinical qualification, professional certification, or continuing education credit. Illustrations are simplified and should not be used as clinical references.</p><h2>Accounts</h2><p>When registration is activated, use accurate account information and keep your credentials private. Do not upload patient information or sensitive medical records. Saved progress reflects your learning activity and is not proof of professional competence.</p><h2>Availability and external resources</h2><p>Features depend on hosting, network access, and configured third-party services. External resources have their own terms and privacy practices. No payment or paid course entitlement is implemented on this site.</p><h2>Questions and corrections</h2><p>Use the contact page to ask about course material or report a correction once operator contact details are available. The operator must finalize applicable business and legal terms before opening registration.</p></section>''')
page('404.html','Page not found','''<section class="cta"><div class="eyebrow">A small detour</div><h1>This chapter<br>isn’t here.</h1><p style="margin-top:25px">The page may have moved. Your next lesson is still waiting.</p><div class="actions" style="justify-content:center"><a class="btn primary" href="index.html">Back home ↗</a><a class="btn" href="courses.html">Explore courses</a></div></section>''')
